-- skill line IDs, so a German or French client matches too (GetProfessionInfo names are localized; Sol review)
local SKILL = { Alchemy = 171, Blacksmithing = 164, Enchanting = 333, Engineering = 202, Herbalism = 182,
    Mining = 186, Skinning = 393, Tailoring = 197, Leatherworking = 165, Fishing = 356, Cooking = 185,
    ["First Aid"] = 129 }

-- the professions this character has, by English name AND skill line ID. nil = not loaded yet; an empty
-- table = loaded, none learned (a fresh character: their picks and poles are not "needed"; Sol review).
local profs, profsAt, loginAt = nil, 0, nil
local function Profs()
    if profs and GetTime() - profsAt < 10 then return profs end
    if not GetProfessions then return nil end
    local t, n = {}, 0
    local list = { GetProfessions() }   -- primary, primary, archaeology, fishing, cooking[, first aid] (any can be nil)
    for i = 1, 6 do   -- first aid can come 6th on a Classic-style list
        local idx = list[i]
        if idx then
            local name, _, _, _, _, _, line = GetProfessionInfo(idx)
            if type(name) == "string" and not (issecretvalue and issecretvalue(name)) then t[name] = true; n = n + 1 end
            if type(line) == "number" and not (issecretvalue and issecretvalue(line)) then t[line] = true; n = n + 1 end
        end
    end
    -- none found: trust it only a while after login (skill data comes in after the loading screen)
    if n == 0 and not (loginAt and GetTime() - loginAt > 10) then return nil end
    profs, profsAt = t, GetTime()
    return profs
end

local CLASS_NAME = { WARRIOR = "Warrior", PALADIN = "Paladin", HUNTER = "Hunter", ROGUE = "Rogue", PRIEST = "Priest",
    SHAMAN = "Shaman", MAGE = "Mage", WARLOCK = "Warlock", DRUID = "Druid" }

-- Does this character need the item? -> the reason ("Mining", "Fishing", "Rogue") or nil.
-- Professions not loaded yet (right after login): every listed item counts as needed, to be safe.
function ns.ToolNeeded(itemID)
    if type(itemID) ~= "number" or (issecretvalue and issecretvalue(itemID)) then return nil end
    local need = NEED[itemID]
    if not need then
        local ok, _, _, _, _, _, classID, subID = pcall(C_Item.GetItemInfoInstant, itemID)
        if ok and classID == 2 and subID == 20 then need = "Fishing" end   -- every fishing pole
    end
    if not need then return nil end
    local classes = need:match("^class:(.+)$")
    if classes then
        local _, me = UnitClass("player")
        for c in classes:gmatch("[^,]+") do
            if c == me then return CLASS_NAME[me] or me end
        end
        return nil
    end
    local p = Profs()
    if not p then return need:match("^[^,]+") end
    for prof in need:gmatch("[^,]+") do
        if p[prof] or (SKILL[prof] and p[SKILL[prof]]) then return prof end
    end
    return nil
end

-- ONE copy is kept, not every copy (the user, 2026-11-10: "for example i get a better pole", "or what if
-- someone makes poles"). Per kind (the same need, e.g. every Mining tool, every fishing pole): the one you
-- have equipped, else the highest item level in your bags; the rest are spares you can sell. Stackables
-- (Flash Powder, wood, candles...) are all kept: you use them up. Rebuilt when bags or gear change.
local kept, dirty = {}, true
local function KindOf(itemID)
    if KIND[itemID] then return KIND[itemID] end
    if NEED[itemID] then return "id" .. itemID end
    return "Fishing"   -- ToolNeeded already said it's needed, so a non-listed item is a fishing pole
end
-- Stack size not loaded yet counts as stackable: every copy kept until it loads (GET_ITEM_INFO_RECEIVED
-- rebuilds), so a second stack of powder is never left sellable (Sol review).
local function Stackable(itemID)
    local ok, n = pcall(C_Item.GetItemMaxStackSizeByID, itemID)
    if not (ok and type(n) == "number") or (issecretvalue and issecretvalue(n)) then return true end
    return n > 1
end
local function Level(itemID)
    local _, _, _, lvl = C_Item.GetItemInfo(itemID)
    return lvl or 0
end
local function Rebuild()
    kept, dirty = {}, false
    local best = {}
    for inv = 16, 18 do   -- an equipped pole / tool is the one in use: every bag copy is a spare
        local id = GetInventoryItemID("player", inv)
        if id and not (issecretvalue and issecretvalue(id)) and ns.ToolNeeded(id) and not Stackable(id) then
            best[KindOf(id)] = { score = math.huge }
        end
    end
    local last = (Enum and Enum.BagIndex and Enum.BagIndex.ReagentBag) or NUM_BAG_SLOTS or 4
    for bag = 0, last do
        for slot = 1, C_Container.GetContainerNumSlots(bag) do
            local id = C_Container.GetContainerItemID(bag, slot)
            if id and not (issecretvalue and issecretvalue(id)) then
                local why = ns.ToolNeeded(id)
                if why then
                    local key = bag * 1000 + slot
                    if Stackable(id) then
                        kept[key] = why
                    else
                        local kind, score = KindOf(id), Level(id)
                        local b = best[kind]
                        if not b or score > b.score then best[kind] = { score = score, key = key, why = why } end
                    end
                end
            end
        end
    end
    for _, b in pairs(best) do
        if b.key then kept[b.key] = b.why end
    end
end

-- Is THIS bag slot the copy to keep? -> the reason ("Mining", "Fishing", "Rogue") or nil (a spare, or not needed)
function ns.ToolKept(bag, slot)
    if type(bag) ~= "number" or type(slot) ~= "number" then return nil end
    if dirty then Rebuild() end
    return kept[bag * 1000 + slot]
end

local ev = CreateFrame("Frame")
for _, e in ipairs({ "BAG_UPDATE_DELAYED", "PLAYER_EQUIPMENT_CHANGED", "SKILL_LINES_CHANGED", "PLAYER_LOGIN",
    "GET_ITEM_INFO_RECEIVED" }) do
    pcall(ev.RegisterEvent, ev, e)
end
ev:SetScript("OnEvent", function(_, e)
    dirty = true; profs = nil
    if e == "PLAYER_LOGIN" then
        loginAt = GetTime()
        C_Timer.After(12, function() dirty = true; profs = nil end)   -- "no professions" becomes trusted
    end
end)
